package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_evaluation_session") public class EvaluationSession extends RspAuditedEntity{
 public enum Status{DRAFT,SCHEDULED,COMPLETED,CANCELLED} public enum DeliveryMode{ONSITE,REMOTE_APPROVED,HYBRID}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="stage_id",nullable=false,length=36)private String stageId;@Column(name="session_revision",nullable=false)private int sessionRevision;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Column(name="time_zone",nullable=false,length=80)private String timeZone;@Enumerated(EnumType.STRING)@Column(name="delivery_mode",nullable=false,length=30)private DeliveryMode deliveryMode;@Column(length=500)private String venue;@Column(length=2000)private String instructions;private Integer capacity;@Column(name="responsible_employee_no",nullable=false,length=100)private String responsibleEmployeeNo;@Column(name="scheduled_by",length=100)private String scheduledBy;@Column(name="scheduled_at")private Instant scheduledAt;@Column(name="completed_by",length=100)private String completedBy;@Column(name="completed_at")private Instant completedAt;@Column(name="cancelled_by",length=100)private String cancelledBy;@Column(name="cancelled_at")private Instant cancelledAt;@Column(name="change_reason",length=2000)private String changeReason;
 protected EvaluationSession(){} public EvaluationSession(String agency,String proceeding,String stage,int revision,Instant starts,Instant ends,String zone,DeliveryMode mode,String venue,String instructions,Integer capacity,String responsible){super(agency);proceedingId=requiredText(proceeding,"proceedingId");stageId=requiredText(stage,"stageId");if(revision<1)throw new IllegalArgumentException("sessionRevision must be positive");sessionRevision=revision;apply(starts,ends,zone,mode,venue,instructions,capacity,responsible);status=Status.DRAFT;}
 public void update(Instant starts,Instant ends,String zone,DeliveryMode mode,String venue,String instructions,Integer capacity,String responsible,String reason){if(status!=Status.DRAFT&&status!=Status.SCHEDULED)throw new IllegalLifecycleTransitionException("Only a DRAFT or SCHEDULED session may be changed");if(status==Status.SCHEDULED)changeReason=requiredText(reason,"changeReason");apply(starts,ends,zone,mode,venue,instructions,capacity,responsible);}
 public void schedule(String actor,Instant at){if(status!=Status.DRAFT&&status!=Status.SCHEDULED)throw new IllegalLifecycleTransitionException("Only a DRAFT session may be scheduled");scheduledBy=requiredText(actor,"actor");scheduledAt=Objects.requireNonNull(at);status=Status.SCHEDULED;}
 public void complete(String actor,Instant at){if(status!=Status.SCHEDULED)throw new IllegalLifecycleTransitionException("Only a SCHEDULED session may be completed");completedBy=requiredText(actor,"actor");completedAt=Objects.requireNonNull(at);status=Status.COMPLETED;}
 public void cancel(String actor,String reason,Instant at){if(status==Status.COMPLETED||status==Status.CANCELLED)throw new IllegalLifecycleTransitionException("A completed or cancelled session cannot be cancelled");String a=requiredText(actor,"actor"),r=requiredText(reason,"reason");Instant t=Objects.requireNonNull(at);cancelledBy=a;changeReason=r;cancelledAt=t;status=Status.CANCELLED;}
 private void apply(Instant starts,Instant ends,String zone,DeliveryMode mode,String v,String i,Integer cap,String responsible){startsAt=Objects.requireNonNull(starts);endsAt=Objects.requireNonNull(ends);if(!ends.isAfter(starts))throw new IllegalArgumentException("endsAt must be after startsAt");timeZone=requiredText(zone,"timeZone");ZoneId.of(timeZone);deliveryMode=Objects.requireNonNull(mode);venue=optionalText(v);instructions=optionalText(i);if(cap!=null&&cap<1)throw new IllegalArgumentException("capacity must be positive");capacity=cap;responsibleEmployeeNo=requiredText(responsible,"responsibleEmployeeNo");}
 public String getProceedingId(){return proceedingId;}public String getStageId(){return stageId;}public int getSessionRevision(){return sessionRevision;}public Status getStatus(){return status;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public String getTimeZone(){return timeZone;}public DeliveryMode getDeliveryMode(){return deliveryMode;}public String getVenue(){return venue;}public String getInstructions(){return instructions;}public Integer getCapacity(){return capacity;}public String getResponsibleEmployeeNo(){return responsibleEmployeeNo;}public String getScheduledBy(){return scheduledBy;}public Instant getScheduledAt(){return scheduledAt;}public String getCompletedBy(){return completedBy;}public Instant getCompletedAt(){return completedAt;}public String getCancelledBy(){return cancelledBy;}public Instant getCancelledAt(){return cancelledAt;}public String getChangeReason(){return changeReason;}
}
